INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422571, 15983, 'The Guardian', 'en', 'South Korea to re-examine 310,000 missing person cases after fake record scandal', 'https://www.theguardian.com/world/2026/aug/28/south-korea-missing-persons-police-scandal-bodies-jeju', 'Renewed scrutiny comes after police officer accused of falsifying records in order to close the cases of people who were later found dead South Korean police will re-examine about 310,000 missing persons cases closed over the past three years, prompted by a scandal in which an officer was arrested on suspicion of falsifying records to close files on two people who were later found dead. The case has drawn national attention, with President Lee Jae Myung ordering an investigation into the police handling of it and telling the force to draw up a reform plan. Continue reading...', 'https://i.guim.co.uk/img/media/e64544af30657fd0f55b257a91b44800fa60e1af/174_1613_3619_2895/master/3619.jpg?width=140&quality=85&auto=format&fit=max&s=5b6d23db3b3dc5881bde9977f84f8c06', '2026-08-28T03:06:40+00:00', '2026-08-28T12:49:05.634234'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
