INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (424278, 15983, 'Le Monde', 'en', 'South Korea says will hold joint military drills with US and Japan', 'https://www.lemonde.fr/en/international/article/2026/08/28/south-korea-says-will-hold-joint-military-drills-with-us-and-japan_6756931_4.html', 'The three allies will carry out air defense, maritime missile defense, anti-submarine and cyber defense exercises, even as Donald Trump seeks to revive dialogue with Pyongyang.', 'https://img.lemde.fr/2026/08/21/58/0/2862/1431/644/322/60/0/3b40950_ftp-1-zmuwidlbxhtv-2026-08-21t112627z-433179406-rc2z2naq96ga-rtrmadp-3-southkorea-usa-military.JPG', '2026-08-28T08:50:53+00:00', '2026-08-28T12:51:44.427358'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (425246, 15983, 'South China Morning Post', 'en', 'South Korea backs Trump’s North Korea outreach, but warns against being sidelined', 'https://www.scmp.com/news/asia/east-asia/article/3365542/south-korea-backs-trumps-north-korea-outreach-warns-against-being-sidelined', 'South Korea supports US President Donald Trump’s efforts to resume dialogue with North Korea, ‌but aims to ensure its security posture is not weakened and that Seoul is not sidelined, according to South Korea’s national security adviser. Seoul believed the resumption of talks between the US and North Korea should focus on progress on the North Korean nuclear weapons issue and must not undermine the country’s security readiness, Wi Sung-lac told reporters on Friday. “One point to keep in mind is...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/28/687035a4-cedf-4112-9db8-0e438fd8a77f_0c295674.jpg?itok=4gLvxqqi&v=1787892993', '2026-08-28T04:56:43+00:00', '2026-08-28T12:53:51.939943'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (425252, 15983, 'South China Morning Post', 'en', 'South Korea, Japan and US set joint drills despite Trump cuts', 'https://www.scmp.com/news/asia/east-asia/article/3365527/south-korea-japan-and-us-set-joint-drills-despite-trump-cuts', 'South Korea said on Friday it would hold joint military exercises with the United States and Japan in September, after Washington scaled back annual drills with Seoul in an apparent bid to encourage dialogue with North Korea. The three countries would conduct the North Korea-focused Freedom Edge exercise from September 7 to 11 in international waters east and south of South Korea’s Jeju Island, Seoul’s Joint Chiefs of Staff (JCS) said. “This exercise is a defensive drill conducted annually by...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/28/b80c14e0-6305-4155-9a95-33f21f19ed28_a7877ca5.jpg?itok=uvp6yHVi&v=1787888135', '2026-08-28T03:35:37+00:00', '2026-08-28T12:53:51.999549'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
